import pyodide.http
import json
def shows_in_production(startYear, endYear):
    url = 'https://jsonmock.hackerrank.com/api/tvseries?page='
    page = 1
    totalp = 1
    ans = []
    while page <= totalp:
        res = json.loads(pyodide.http.open_url(url + str(page)).read())
        totalp = res['total_pages']
        for d in res['data']:
            a = d['runtime_of_series']
            b = a.replace('(', '').replace(')', '').replace('II', '').replace('I', '').strip()
            if '-' in b:
                c = b.split('-')
                start = int(c[0])
                end = int(c[1]) if len(c)>1 and c[1].strip() else None
            else:
                start = int(b)
                end = start
            if start >= startYear:
                if endYear == -1 and end is None:
                    ans.append(d['name'])
                elif end is not None and end <= endYear:
                    ans.append(d['name'])
        page += 1
    return sorted(ans)
if __name__ == '__main__':
    import sys
    lines = sys.stdin.read().splitlines()
    if len(lines) >= 2:
        startYear = int(lines[0].strip())
        endYear = int(lines[1].strip())
        res = shows_in_production(startYear, endYear)
        if res:
            print(','.join(res))

