async function showsInProduction(startYear, endYear) {
    const url = 'https://jsonmock.hackerrank.com/api/tvseries?page=';
    let page = 1; let totalp = 1;
    let ans = [];
    while(page <= totalp){
        const res = await fetch(`${url}${page}`);
        const result = await res.json();
        totalp = result.total_pages;
        for(let d of result.data){
            let b = d.runtime_of_series.replaceAll('(', '').replaceAll(')', '').replaceAll('II', '').replaceAll('I', '').trim();
            let start, end;
            if(b.includes('-')){
                let c = b.split('-');
                start = Number(c[0]);
                end = c[1] ? Number(c[1]) : null;
            } else {
                start = Number(b);
                end = start;
            }
            if(start >= startYear){
                if(endYear === -1 && end === null) ans.push(d.name);
                else if(end !== null && end <= endYear) ans.push(d.name);
            }
        }
        page++;
    }
    return ans.sort();
}
