async function findSpeedster(marathon, sex) {
    const url = `https://jsonmock.hackerrank.com/api/marathon?sex=${encodeURIComponent(sex)}&page=`;
    let page = 1; let totalp = 1;
    let ans = ''; let speed = -Infinity; let stop = Infinity;
    while(page <= totalp){
        const res = await fetch(`${url}${page}`);
        const result = await res.json();
        totalp = result.total_pages;
        for(let d of result.data){
            if(d.marathon_name === marathon){
                let speedd = parseFloat(d.top_speed);
                let stopp = parseInt(d.stops_taken);
                if(speedd > speed || (speed === speedd && stopp < stop)){
                    speed = speedd;
                    ans = d.name;
                    stop = stopp;
                }
            }
        }
        page++;
    }
    return ans;
}
