async function bestUniversityByCountry(country) {
    const url = 'https://jsonmock.hackerrank.com/api/universities?page=';
    let page = 1; let totalp = 1;
    let best_rank = Infinity; let best_name = '';
    while(page <= totalp){
        const res = await fetch(`${url}${page}`);
        const result = await res.json();
        totalp = result.total_pages;
        for(let u of result.data){
            if(u.location.country.toLowerCase() === country.toLowerCase()){
                let rank = u.rank_display;
                if(rank && /^\d+$/.test(rank)){
                    let numRank = parseInt(rank);
                    if(numRank < best_rank){
                        best_rank = numRank;
                        best_name = u.university;
                    }
                }
            }
        }
        page++;
    }
    return best_name;
}
if (typeof input !== 'undefined') {
    const lines = input.split('\n').filter(l => l.trim() !== '');
    if (lines.length >= 1) {
        const res = await bestUniversityByCountry(lines[0]);
        if (res) console.log(res);
    }
}
